def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        safe_bid = DAILY_SALARY * 0.25
        if hp <= 2 or no_water_days >= 2:
            safe_bid = DAILY_SALARY * 0.7
        return float(min(budget, safe_bid))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 8:
            rich_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.7
    elif hp <= 4:
        urgency += 0.4
    if no_water_days >= 2:
        urgency += 0.7
    elif no_water_days == 1:
        urgency += 0.25
    if day >= 8:
        urgency += 0.1
    if urgency > 1.2:
        urgency = 1.2

    base = DAILY_SALARY * (0.28 + 0.42 * scarcity + 0.35 * min(1.0, urgency))

    pressure_bid = 0.0
    if highest_prev >= 120:
        pressure_bid = DAILY_SALARY * (0.52 + 0.18 * scarcity)
    elif highest_prev >= 75:
        pressure_bid = min(highest_prev * 0.92 + 1.0, DAILY_SALARY * 1.02)
    elif highest_prev > 0:
        pressure_bid = max(DAILY_SALARY * 0.42, avg_prev + 2.0)
    else:
        pressure_bid = DAILY_SALARY * 0.35

    bid = max(base, pressure_bid)

    if supply >= 22 and urgency < 0.5:
        bid *= 0.78
    elif supply <= 17:
        bid *= 1.18

    if desperate_count >= 2:
        bid *= 1.08
    if rich_count >= 2 and supply <= 18:
        bid *= 1.07

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, DAILY_SALARY * 0.92)
    elif hp <= 4 or no_water_days == 1:
        bid = max(bid, DAILY_SALARY * 0.68)

    if day == 1 and supply >= 20:
        bid = min(bid, DAILY_SALARY * 0.48)

    max_affordable = budget
    if day < 10:
        reserve = max(0.0, (10 - day) * DAILY_SALARY * 0.08)
        max_affordable = max(0.0, budget - reserve)
        if hp <= 3 or no_water_days >= 2:
            max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    total_water_needed_by_alive = WATER_REQ
    for opp in alive_opponents:
        total_water_needed_by_alive += opp['water_requirement']

    base_bid_value = DAILY_SALARY * 0.6

    if current_supply < total_water_needed_by_alive:
        base_bid_value = DAILY_SALARY * 0.8
    elif current_supply > total_water_needed_by_alive * 1.5:
        base_bid_value = DAILY_SALARY * 0.4

    if my_hp <= 2:
        bid = DAILY_SALARY * 0.99
    elif my_hp <= 4:
        bid = DAILY_SALARY * 0.85
    else:
        bid = base_bid_value

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_hp <= 3:
                bid = max(bid, highest_prev_bid * 1.05)
            else:
                bid = max(bid, highest_prev_bid * 1.01)
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            bid = max(bid, highest_prev_bid + 2)
        else:
            bid = max(bid, highest_prev_bid + 1)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2 and my_hp > 0:
        if my_hp <= 2:
            bid = max(bid, DAILY_SALARY * 0.99)
        elif my_budget > DAILY_SALARY * 0.5:
            bid = max(bid, DAILY_SALARY * 0.9)

    bid = min(my_budget, bid)
    bid = max(0.01, bid)

    return bid

